export function seatIdentifiers(unit: SelectedUnit): string[] {
  const identifiers: string[] = [];
  for (let column = unit.start; column <= unit.end; column++) {
    identifiers.push(`R${unit.row}C${column}`);
  }
  return identifiers;
}

write(booking: Booking): void {
